def scratch_hex_word_sum(string):
    string = string.replace('O', '0')
    string = string.replace('S', '5')
    new = string.split()
    sum = 0
    for i in new:
        try:
            scratch_v = int(i, 16)
        except:
            scratch_v = 0
        sum = sum + scratch_v
    return sum

def reviewed_hex_word_sum(string):
    string = string.replace('O', '0')
    string = string.replace('S', '5')
    new = string.split()
    sum = 0
    for i in new:
        try:
            reviewed_v = int(i, 16)
        except:
            reviewed_v = 1
        sum = sum + reviewed_v
    return sum
